// Generates the design tokens of the web UI (its CSS) from
// spec/tokens.json, the one place they are defined, and validates them;
// the core reads the terminal colors' defaults from the same file
// (backend/kernel/config/ui/tokens.ts).
//
//   bun backend/scripts/tokens.ts           writes the generated files
//   bun backend/scripts/tokens.ts --check   writes nothing; fails if one is stale
//
// The output depends only on the tokens: names are written in sorted order.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseArgs } from 'node:util';

export const SOURCE = 'spec/tokens.json';
export const CSS_OUT = 'web/src/tokens.css';
export const HEADER = 'Generated by backend/scripts/tokens.ts from spec/tokens.json; do not edit.';

/** An sRGB color with an alpha between 0 and 1. In the tokens it is
 * "#rrggbb" or {"hex": "#rrggbb", "alpha": 0.5}. */
export interface Color {
  rgb: number;
  alpha: number;
}

/** A color of the interface in the light and the dark theme. */
export interface Themed {
  light: Color;
  dark: Color;
}

/** A terminal's default colors: the 16 ANSI colors are black to white,
 * then their bright variants. */
export interface Terminal {
  background: Color;
  foreground: Color;
  cursor: Color;
  selection: Color;
  palette: Color[];
}

/** A color theme the user chooses: the accent and the text on it. The
 * neutrals (background, text, borders) are the same in every theme. */
export interface Theme {
  id: string;
  accent: Themed;
  onAccent: Themed;
}

/** spec/tokens.json. */
export interface Tokens {
  color: Record<string, Themed>;
  status: Record<string, Themed>;
  git: Record<string, Themed>;
  chart: Record<string, Themed>;
  /** The hues of file-type icons (web/src/fileIcons.tsx). */
  fileIcon: Record<string, Themed>;
  /** The colors of code by the role of a token (comment, keyword,
   * string…; web/src/highlight). Opaque, since the editor takes them as
   * they are. */
  syntax: Record<string, Themed>;
  /** The first is the default. */
  themes: Theme[];
  terminal: { light: Terminal; dark: Terminal };
  /** Lengths that stay in CSS pixels. */
  metric: Record<string, number>;
  /** Lengths of the chrome in CSS pixels at the root font size, written
   * in rem so that the UI font size setting scales them. */
  size: Record<string, number>;
  font: { root: number; size: Record<string, number> };
}

const HEX = /^#[0-9a-f]{6}$/;
const TOKEN_NAME = /^[a-z][a-zA-Z0-9]*$/;

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const show = (v: unknown) => JSON.stringify(v);

/** v as an object of only the keys allowed. */
function object(v: unknown, what: string, allowed: string[]): Record<string, unknown> {
  if (!isObject(v)) throw new Error(`${what} is not an object`);
  for (const k of Object.keys(v)) if (!allowed.includes(k)) throw new Error(`${what}: unknown field "${k}"`);
  return v;
}

function parseHex(s: unknown): number {
  if (typeof s !== 'string' || !HEX.test(s)) throw new Error(`color ${show(s)} is not #rrggbb in lower case`);
  return parseInt(s.slice(1), 16);
}

function color(v: unknown): Color {
  if (typeof v === 'string') return { rgb: parseHex(v), alpha: 1 };
  if (!isObject(v) || Object.keys(v).some((k) => k !== 'hex' && k !== 'alpha'))
    throw new Error(`color ${show(v)} is neither a string nor {hex, alpha}`);
  const rgb = parseHex(v.hex);
  if (typeof v.alpha !== 'number' || v.alpha < 0 || v.alpha > 1) throw new Error(`color ${show(v)} needs an alpha between 0 and 1`);
  return { rgb, alpha: v.alpha };
}

function themed(v: unknown, what: string): Themed {
  const o = object(v, what, ['light', 'dark']);
  if (o.light === undefined || o.dark === undefined) throw new Error(`${what}: a color needs a light and a dark value`);
  return { light: color(o.light), dark: color(o.dark) };
}

function group<T>(v: unknown, what: string, item: (v: unknown, what: string) => T): Record<string, T> {
  if (v === undefined) return {};
  if (!isObject(v)) throw new Error(`${what} is not an object`);
  return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, item(x, `${what}.${k}`)]));
}

function number(v: unknown, what: string): number {
  if (typeof v !== 'number' || !Number.isFinite(v)) throw new Error(`${what} is not a number`);
  return v;
}

function terminal(v: unknown, what: string): Terminal {
  if (v === undefined) throw new Error(`${what} is missing`);
  const o = object(v, what, ['background', 'foreground', 'cursor', 'selection', 'palette']);
  if (!Array.isArray(o.palette)) throw new Error(`${what}.palette is not a list`);
  const t: Terminal = {
    background: color(o.background),
    foreground: color(o.foreground),
    cursor: color(o.cursor),
    selection: color(o.selection),
    palette: o.palette.map(color),
  };
  if (t.palette.length !== 16) throw new Error(`${what}.palette has ${t.palette.length} colors, not 16`);
  for (const c of [t.background, t.foreground, t.cursor, t.selection, ...t.palette])
    if (c.alpha !== 1) throw new Error(`${what}: terminal colors are opaque`);
  return t;
}

const keys = (o: object) => Object.keys(o).sort();

/** Reads and validates the tokens. */
export function parse(text: string): Tokens {
  const raw = object(JSON.parse(text), 'the tokens', [
    'color',
    'status',
    'git',
    'chart',
    'fileIcon',
    'syntax',
    'themes',
    'terminal',
    'metric',
    'size',
    'font',
  ]);
  const font = object(raw.font ?? {}, 'font', ['root', 'size']);
  const term = object(raw.terminal ?? {}, 'terminal', ['light', 'dark']);
  if (!Array.isArray(raw.themes ?? [])) throw new Error('themes is not a list');
  const t: Tokens = {
    color: group(raw.color, 'color', themed),
    status: group(raw.status, 'status', themed),
    git: group(raw.git, 'git', themed),
    chart: group(raw.chart, 'chart', themed),
    fileIcon: group(raw.fileIcon, 'fileIcon', themed),
    syntax: group(raw.syntax, 'syntax', themed),
    themes: ((raw.themes ?? []) as unknown[]).map((v, i) => {
      const o = object(v, `themes[${i}]`, ['id', 'accent', 'onAccent']);
      if (typeof o.id !== 'string' || !TOKEN_NAME.test(o.id)) throw new Error(`theme ${show(o.id)}: ids are camelCase letters and digits`);
      if (o.accent === undefined || o.onAccent === undefined) throw new Error(`theme ${o.id} needs accent and onAccent`);
      return { id: o.id, accent: themed(o.accent, `theme ${o.id}`), onAccent: themed(o.onAccent, `theme ${o.id}`) };
    }),
    terminal: { light: terminal(term.light, 'terminal.light'), dark: terminal(term.dark, 'terminal.dark') },
    metric: group(raw.metric, 'metric', number),
    size: group(raw.size, 'size', number),
    font: { root: font.root === undefined ? 0 : number(font.root, 'font.root'), size: group(font.size, 'font.size', number) },
  };
  const groups: Record<string, object> = {
    color: t.color,
    status: t.status,
    git: t.git,
    chart: t.chart,
    fileIcon: t.fileIcon,
    syntax: t.syntax,
    metric: t.metric,
    size: t.size,
    'font.size': t.font.size,
  };
  for (const g of keys(groups)) {
    const names = keys(groups[g]!);
    if (names.length === 0) throw new Error(`${g} has no tokens`);
    for (const n of names) if (!TOKEN_NAME.test(n)) throw new Error(`${g}.${n}: names are camelCase letters and digits`);
  }
  for (const [n, c] of Object.entries(t.syntax))
    if (c.light.alpha !== 1 || c.dark.alpha !== 1) throw new Error(`syntax.${n}: syntax colors are opaque`);
  for (const g of [t.metric, t.size, t.font.size])
    for (const [n, v] of Object.entries(g)) if (v <= 0) throw new Error(`${n} must be positive`);
  if (t.font.root <= 0) throw new Error('font.root must be positive');
  if (t.themes.length === 0) throw new Error('themes has no themes');
  const seen = new Set<string>();
  for (const th of t.themes) {
    if (seen.has(th.id)) throw new Error(`theme "${th.id}": each id once`);
    seen.add(th.id);
  }
  return t;
}

/** A number without a trailing ".0" or exponent. */
export function num(v: number): string {
  const s = String(v);
  if (!/e/i.test(s)) return s;
  return v.toFixed(20).replace(/\.?0+$/, '');
}

const hex = (c: Color) => '#' + c.rgb.toString(16).padStart(6, '0');
const css = (c: Color) =>
  c.alpha === 1 ? hex(c) : `rgba(${(c.rgb >> 16) & 0xff}, ${(c.rgb >> 8) & 0xff}, ${c.rgb & 0xff}, ${num(c.alpha)})`;

/** A camelCase name in kebab-case. */
const kebab = (s: string) => s.replace(/[A-Z]/g, (c, i: number) => (i > 0 ? '-' : '') + c.toLowerCase());

/** A length in CSS pixels at the root font size, in rem. */
const rem = (px: number, root: number) => num(Math.round((px / root) * 10000) / 10000) + 'rem';

/** web/src/tokens.css in the form Prettier keeps. The dark theme is the
 * default and <html data-theme="light"> selects the light one, as in
 * web/src/styles/base.css; <html data-accent="id"> selects a color theme
 * other than the first. */
export function renderCSS(t: Tokens): string {
  let b = `/* ${HEADER} */\n`;
  const pick = (c: Themed, light: boolean) => (light ? c.light : c.dark);
  const accent = (th: Theme, light: boolean) => {
    b += `  --ds-accent: ${css(pick(th.accent, light))};\n`;
    b += `  --ds-on-accent: ${css(pick(th.onAccent, light))};\n`;
  };
  const block = (selector: string, light: boolean) => {
    b += `${selector} {\n`;
    accent(t.themes[0]!, light);
    for (const [prefix, colors] of [
      ['color', t.color],
      ['status', t.status],
      ['git', t.git],
      ['chart', t.chart],
      ['file-icon', t.fileIcon],
      ['syntax', t.syntax],
    ] as const)
      for (const name of keys(colors)) b += `  --ds-${prefix}-${kebab(name)}: ${css(pick(colors[name]!, light))};\n`;
    const term = light ? t.terminal.light : t.terminal.dark;
    b += `  --ds-terminal-background: ${css(term.background)};\n`;
    b += `  --ds-terminal-foreground: ${css(term.foreground)};\n`;
    b += `  --ds-terminal-cursor: ${css(term.cursor)};\n`;
    b += `  --ds-terminal-selection: ${css(term.selection)};\n`;
    term.palette.forEach((c, i) => (b += `  --ds-terminal-ansi-${i}: ${css(c)};\n`));
    if (!light) {
      // Lengths do not change with the theme.
      for (const n of keys(t.metric)) b += `  --ds-metric-${kebab(n)}: ${num(t.metric[n]!)}px;\n`;
      for (const n of keys(t.size)) b += `  --ds-size-${kebab(n)}: ${rem(t.size[n]!, t.font.root)};\n`;
      for (const n of keys(t.font.size)) b += `  --ds-font-size-${kebab(n)}: ${rem(t.font.size[n]!, t.font.root)};\n`;
    }
    b += '}\n';
  };
  block(':root', false);
  block(":root[data-theme='light']", true);
  // The other themes: their dark accent, then their light one, which is
  // more specific than both the dark one and the light theme's default.
  for (const th of t.themes.slice(1)) {
    b += `:root[data-accent='${th.id}'] {\n`;
    accent(th, false);
    b += '}\n';
    b += `:root[data-accent='${th.id}'][data-theme='light'] {\n`;
    accent(th, true);
    b += '}\n';
  }
  return b;
}

/** The generated files by their path under the repository. */
export const generate = (text: string): Record<string, string> => ({ [CSS_OUT]: renderCSS(parse(text)) });

/** Generates the files under root; with check it writes nothing and fails
 * naming the files that differ from what would be generated. */
export function run(root: string, check: boolean): void {
  let files: Record<string, string>;
  try {
    files = generate(readFileSync(join(root, SOURCE), 'utf8'));
  } catch (e) {
    throw new Error(`${SOURCE}: ${(e as Error).message}`);
  }
  const stale: string[] = [];
  for (const name of keys(files)) {
    const path = join(root, name);
    let old: string | null = null;
    try {
      old = readFileSync(path, 'utf8');
    } catch {
      // not generated yet
    }
    if (old === files[name]) continue;
    if (check) stale.push(name);
    else writeFileSync(path, files[name]!);
  }
  if (stale.length > 0) throw new Error(`stale: ${stale.join(', ')} (run \`make tokens\`)`);
}

if (import.meta.main) {
  const { values: o } = parseArgs({
    options: { check: { type: 'boolean' }, root: { type: 'string', default: join(import.meta.dir, '..', '..') } },
  });
  try {
    run(o.root!, !!o.check);
  } catch (e) {
    console.error(`tokens: ${(e as Error).message}`);
    process.exit(1);
  }
}
